parameters.query:
SELECT ARRAY_REMOVE(ARRAY_AGG(DISTINCT ghl_contact_id), NULL) AS enrolled_contact_ids
FROM "SimpleTexting_Campaign_State"
WHERE campaign_key = 'simpletexting_campaign_v1' AND status IN ('enrolled','sent_step_1','sent_step_2','sent_step_3','sent_step_4','sent_step_5','finished','delivery_failed','awaiting_phone_refresh','stopped');

