const cfg = $item(0).$node['Config'].json || {};
const state = $item(0).$node['Fetch Campaign Enrollment State'].json || {};

function clean(v) { return String(v ?? '').trim(); }
function parseBoolean(v, fallback) {
  if (v === undefined || v === null || v === '') return fallback;
  if (typeof v === 'boolean') return v;
  const s = String(v).trim().toLowerCase();
  if (['true','1','yes','y'].includes(s)) return true;
  if (['false','0','no','n'].includes(s)) return false;
  return fallback;
}
function normalizePhone(v) {
  const digits = clean(v).replace(/\D/g, '');
  if (!digits) return '';
  if (digits.length === 11 && digits.startsWith('1')) return digits.slice(1);
  return digits;
}
function normalizeTagList(value) {
  if (Array.isArray(value)) return value.map((item) => clean(typeof item === 'string' ? item : item?.name || item?.value)).filter(Boolean).map((v) => v.toLowerCase());
  if (typeof value === 'string') return value.split(',').map((item) => clean(item).toLowerCase()).filter(Boolean);
  return [];
}
async function doHttpRequest(options) {
  if (typeof $httpRequest === 'function') return await $httpRequest(options);
  if (this?.helpers?.httpRequest) return await this.helpers.httpRequest(options);
  throw new Error('HTTP helper not available');
}
async function apiRequest({ method, url, headers, body }) {
  const options = { method, url, headers, json: true };
  if (body !== undefined) options.body = body;
  try {
    const data = await doHttpRequest.call(this, options);
    return { ok: true, data };
  } catch (err) {
    return { ok: false, status: err?.statusCode || err?.httpCode || err?.cause?.statusCode || 500, data: err?.response?.body || err?.message || err };
  }
}
function getContactsArray(data) {
  if (Array.isArray(data?.contacts)) return data.contacts;
  if (Array.isArray(data?.data?.contacts)) return data.data.contacts;
  if (Array.isArray(data?.data)) return data.data;
  return [];
}

const locationId = clean(cfg.locationId);
const apiBaseUrl = clean(cfg.ghlApiBaseUrl || 'https://services.leadconnectorhq.com').replace(/\/$/, '');
const apiKey = clean(cfg.ghlApiKey);
const dryRun = !!cfg.defaultDryRun;
const candidateLimit = Math.max(1, Math.trunc(Number(cfg.candidateLimit || 200)));
const enrolled = new Set(Array.isArray(state.enrolled_contact_ids) ? state.enrolled_contact_ids.map((v) => clean(v)).filter(Boolean) : []);
const searchBodyRaw = clean(cfg.simpletextingPoolSearchBodyJson);
if (!searchBodyRaw) return [];
let searchBody = {};
try { searchBody = JSON.parse(searchBodyRaw); } catch { throw new Error('Config.simpletextingPoolSearchBodyJson is not valid JSON'); }
searchBody.locationId = locationId;
if (searchBody.page == null) searchBody.page = 1;
if (searchBody.pageLimit == null) searchBody.pageLimit = candidateLimit;
const res = await apiRequest.call(this, { method:'POST', url:`${apiBaseUrl}/contacts/search`, headers: { Authorization:`Bearer ${apiKey}`, Version:'2021-07-28', Accept:'application/json', 'Content-Type':'application/json' }, body: searchBody });
if (!res.ok) throw new Error(`SimpleTexting pool search failed: ${JSON.stringify(res.data)}`);
const contacts = getContactsArray(res.data);
const out = [];
for (const contact of contacts) {
  const contactId = clean(contact.id);
  const phone = normalizePhone(contact.phone);
  const tags = normalizeTagList(contact.tags || []);
  if (!contactId || !phone || enrolled.has(contactId)) continue;
  if (tags.includes(String(cfg.tagOngoing || '').toLowerCase()) || tags.includes(String(cfg.tagFinished || '').toLowerCase()) || tags.includes(String(cfg.tagStop || '').toLowerCase())) continue;
  out.push({ json: {
    contactId,
    contactPhone: phone,
    email: clean(contact.email),
    firstName: clean(contact.firstName),
    lastName: clean(contact.lastName),
    campaignKey: clean(cfg.campaignKey || 'simpletexting_campaign_v1'),
    dryRun,
    status: 'enrolled',
    currentStep: 0,
    runId: `${new Date().toISOString()}__simpletexting_pool_dispatch`,
  } });
}
return out;

